 subprocess.run(['ffmpeg','-v','error','-y','-i',str(A/'sounds/grey_wolf/summon_howl.ogg'),'-t','2.5','-af','afade=t=in:st=0:d=0.08,afade=t=out:st=2.3:d=0.2','-ac','1','-ar','44100','-c:a','libvorbis','-q:a','5',str(target)],check=True)
